1	import type * as D from './domain';
2	
3	export type ApiErrorCode =
4	  | 'UNAUTHORIZED' | 'BAD_REQUEST' | 'NOT_FOUND' | 'CONFLICT' | 'RATE_LIMITED'
5	  | 'UPSTREAM_UNAVAILABLE' | 'UNPROCESSABLE' | 'PAYLOAD_TOO_LARGE' | 'INTERNAL';
6	export interface ApiError { error: { code: ApiErrorCode; message: string; details?: unknown } }
7	
8	// ── Profile ────────────────────────────────────────────────────────────────
9	// GET  /api/me                → D.UserProfile
10	// PATCH /api/me               → D.UserProfile
11	export interface UpdateMeRequest {
12	  displayName?: string;
13	  tz?: string;
14	  dailyKcalGoal?: number | null;
15	  dailyProteinGoalG?: number | null;
16	  diets?: D.DietFlag[];
17	  allergens?: D.Allergen[];
18	  completeOnboarding?: boolean;
19	}
20	
21	// ── Products ───────────────────────────────────────────────────────────────
22	// POST /api/products/lookup
23	export interface ProductLookupRequest { barcode: string }          // digits only, 8–14
24	export interface ProviderAttempt {
25	  provider: 'cache' | 'dataandapis' | 'openfoodfacts';
26	  result: 'hit' | 'miss' | 'error' | 'skipped';
27	  httpStatus?: number;
28	  ms: number;
29	}
30	export type ProductLookupResponse =
31	  | { status: 'found'; product: D.Product; cached: boolean; attempts: ProviderAttempt[] }
32	  | { status: 'not_found'; gtin: string; attempts: ProviderAttempt[] }
33	  | { status: 'invalid_barcode'; reason: 'length' | 'check_digit' | 'non_numeric' };
34	
35	// POST /api/vision/label   multipart/form-data: images (1–3 files, each ≤ 4 MB, jpeg/png/webp/heic), gtin?
36	export interface LabelExtractionResponse {
37	  isFoodProduct: boolean;
38	  draft: D.ProductDraft;                      // source = 'gemini_photo'
39	  flaggedFields: Array<keyof D.Nutrients | 'servingSize' | 'packageQuantity' | 'name'>;
40	  macrosConsistent: boolean | null;           // 4p + 4c + 9f ≈ kcal within ±20%
41	  confidence: 'high' | 'medium' | 'low';
42	  notes: string | null;
43	  model: string;
44	}
45	
46	// POST /api/vision/expiry  multipart/form-data: image (1 file ≤ 4 MB)
47	export interface ExpiryExtractionResponse {
48	  rawText: string | null;
49	  dateType: 'best_before' | 'expiry' | 'use_by' | 'packaged_on' | 'sell_by' | 'unknown';
50	  suggestedDate: D.ISODate | null;            // null if packaged_on or unreadable
51	  candidates: D.ISODate[];                    // >1 when order is ambiguous
52	  needsUserChoice: boolean;
53	  yearInferred: boolean;
54	  regexCrossCheck: 'agree' | 'disagree' | 'no_match';
55	  confidence: 'high' | 'medium' | 'low';
56	}
57	
58	// ── Pantry ─────────────────────────────────────────────────────────────────
59	// GET /api/pantry?sort=expiry|name&includeEmpty=false   → ListPantryResponse
60	export interface ListPantryResponse { items: D.PantryItem[] }
61	// POST /api/pantry                                      → D.PantryItem
62	export interface CreatePantryItemRequest {
63	  gtin?: string | null;
64	  name: string;
65	  brand?: string | null;
66	  quantity: number;                           // in displayUnit
67	  displayUnit: D.DisplayUnit;
68	  gramsPerUnit?: number | null;
69	  densityGPerMl?: number | null;
70	  expiryDate?: D.ISODate | null;
71	  expirySource?: 'photo' | 'manual' | null;
72	  expiryRawText?: string | null;
73	  nutritionBasis: '100g' | '100ml' | 'unit';
74	  nutrition?: D.Nutrients | null;             // per basis
75	  servingSizeBase?: number | null;
76	  allergenTags?: D.Allergen[];
77	  source: D.ProductSource;
78	  userVerified: boolean;
79	}
80	// PATCH /api/pantry/:id                                 → D.PantryItem
81	export type UpdatePantryItemRequest =
82	  Partial<Omit<CreatePantryItemRequest, 'source' | 'gtin'>> & { adjustReason?: 'manual_adjust' | 'discard' };
83	// DELETE /api/pantry/:id                                → { ok: true }
84	
85	// ── Recipes ────────────────────────────────────────────────────────────────
86	// POST /api/recipes/search   → application/x-ndjson stream of RecipeSearchEvent (one JSON per line)
87	export interface RecipeSearchRequest {
88	  mustUsePantryItemIds?: D.UUID[];            // default: items with daysToExpiry ≤ 3
89	  freeText?: string;                          // e.g. 'quick dinner', ≤ 100 chars
90	  maxResults?: number;                        // default 6, max 10
91	  extraDiets?: D.DietFlag[];                  // may only ADD to profile filters, never remove
92	}
93	export type RecipeSearchEvent =
94	  | { type: 'status'; stage: 'searching' | 'resolving' | 'fetching' | 'parsing' | 'checking_diet' | 'ranking'; message: string }
95	  | { type: 'search_suggestions'; html: string }      // Gemini searchEntryPoint.renderedContent, render unmodified
96	  | { type: 'candidate'; candidate: D.RecipeCandidate }
97	  | { type: 'excluded'; url: string; reason: 'no_recipe_markup' | 'fetch_failed' | 'diet_violation' | 'allergen' | 'duplicate' | 'blocked_url'; detail?: string }
98	  | { type: 'done'; total: number; excludedCount: number; cached: boolean }
99	  | { type: 'error'; error: ApiError['error'] };
